		account_infos.push(self.payer.clone());
		account_infos.push(self.staking_mint.clone());
		account_infos.push(self.reward_mint.clone());
		account_infos.push(self.staking_config.clone());
		account_infos.push(self.user_stake_position.clone());
		account_infos.push(self.launchpad_reward_accrual.clone());
		account_infos.push(self.dex_reward_accrual.clone());
		account_infos.push(self.user_reward_debt.clone());
